solution.Funcs.java:
import java.util.*;
import java.util.function.*;

class Funcs {
    static <T> UnaryOperator<T> pipeline(List<UnaryOperator<T>> steps) {
        List<UnaryOperator<T>> copy = List.copyOf(steps);
        return x -> {
            T value = x;
            for (UnaryOperator<T> step : copy) value = step.apply(value);
            return value;
        };
    }

    static <T> Predicate<T> allOf(List<Predicate<T>> tests) {
        Predicate<T> result = x -> true;
        for (Predicate<T> t : tests) result = result.and(t);
        return result;
    }

    static <T, R> Function<T, R> memoize(Function<T, R> f) {
        Map<T, R> cache = new HashMap<>();
        return x -> {
            if (!cache.containsKey(x)) cache.put(x, f.apply(x));
            return cache.get(x);
        };
    }

    static Supplier<Integer> counter(int start, int step) {
        int[] next = {start};
        return () -> {
            int value = next[0];
            next[0] += step;
            return value;
        };
    }

    static <T> Map<Boolean, List<T>> split(List<T> items, Predicate<T> test) {
        Map<Boolean, List<T>> result = new HashMap<>();
        result.put(true, new ArrayList<>());
        result.put(false, new ArrayList<>());
        for (T item : items) result.get(test.test(item)).add(item);
        return result;
    }
}

unitTests:
test("pipelines", () -> {
    UnaryOperator<String> clean = Funcs.pipeline(List.of(String::trim, String::toLowerCase, s -> s.replace(' ', '-')));
    checkEq(clean.apply("  Hello World "), "hello-world");
    checkEq(Funcs.<Integer>pipeline(List.of(x -> x + 1, x -> x * 10)).apply(2), 30);
    checkEq(Funcs.<Integer>pipeline(List.of()).apply(7), 7);
});

test("all tests pass", () -> {
    Predicate<String> ok = Funcs.allOf(List.of(s -> !s.isEmpty(), s -> s.length() < 6, s -> Character.isUpperCase(s.charAt(0))));
    checkEq(ok.test("Java"), true);
    checkEq(ok.test("java"), false);
    checkEq(ok.test("Kotlin"), false);
    checkEq(ok.test(""), false);
    checkEq(Funcs.<String>allOf(List.of()).test("anything"), true);
});

test("memoize", () -> {
    int[] calls = {0};
    Function<Integer, Long> slowSquare = n -> { calls[0]++; return (long) n * n; };
    Function<Integer, Long> fast = Funcs.memoize(slowSquare);
    checkEq(fast.apply(4) + fast.apply(4) + fast.apply(5), 57L);
    checkEq(calls[0], 2);
    Function<String, String> nulls = Funcs.memoize(s -> { calls[0]++; return null; });
    nulls.apply("x"); nulls.apply("x");
    checkEq(calls[0], 3);
});

test("counters", () -> {
    Supplier<Integer> a = Funcs.counter(1, 1), b = Funcs.counter(10, -5);
    checkEq(List.of(a.get(), a.get(), a.get()), List.of(1, 2, 3));
    checkEq(List.of(b.get(), b.get()), List.of(10, 5));
    checkEq(a.get(), 4);
});

test("splitting", () -> {
    Map<Boolean, List<Integer>> parts = Funcs.split(List.of(1, 2, 3, 4, 5, 6), n -> n % 3 == 0);
    checkEq(parts.get(true), List.of(3, 6));
    checkEq(parts.get(false), List.of(1, 2, 4, 5));
    checkEq(Funcs.split(List.<String>of(), s -> true).get(false), List.of());
});

